export const markup = (icon: Icon) =>
  `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"${icon.label ? ` aria-label="${icon.label}"` : ''}>${icon.paths
    .map((d) => `<path d="${d}"/>`)
    .join('')}</svg>`

/** The extension’s SVG to JSX rewrite. */
export const toJsx = (svg: string) =>
  svg
    .replace(/class=/g, 'className=')
    .replace(/stroke-width=/g, 'strokeWidth=')
    .replace(/fill-rule=/g, 'fillRule=')
    .replace(/clip-rule=/g, 'clipRule=')

/** Same labelling as the collector: aria-label, or "SVG n". */
